@Timeout(60)
class LmdbBackupWritePerformanceTest {

	@Test
	void blockedPublisherKeepsCommitsWithoutExternalStages(@TempDir Path directory) throws Exception {
		Path live = directory.resolve("live");
		Path backups = directory.resolve("backups");
		LmdbStore store = new LmdbStore(live.toFile(), journaledConfig());
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		store.init();
		try {
			BackupResult full = fullBackup(store, backups);
			store.getBackingStore().backupPublisher().setBeforePublication(() -> {
				entered.countDown();
				try {
					if (!release.await(20, TimeUnit.SECONDS)) {
						throw new AssertionError("The test did not release backup publication");
					}
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new AssertionError(interrupted);
				}
			});
			add(store, "pending-publication");
			assertTrue(entered.await(20, TimeUnit.SECONDS), "The committed stage must reach its publisher");
			try (var files = Files.list(live.resolve(PostCommitBackupPublisher.DIRECTORY))) {
				assertEquals(0L, files.filter(path -> path.getFileName().toString().endsWith(".stage")).count(),
						"Committed backup records must share native atomicity without an external stage per commit");
			}
			release.countDown();
			assertEquals(full.getEndTransactionId() + 1,
					incrementalBackup(store, backups, full.getEndTransactionId()).getEndTransactionId());
		} finally {
			release.countDown();
			store.shutDown();
		}
	}

	@Test
	void ordinaryBackupCommitDoesNotRewriteNamespaceDatabase(@TempDir Path directory) throws Exception {
		Path backups = directory.resolve("backups");
		LmdbStore store = new LmdbStore(directory.resolve("live").toFile(), journaledConfig());
		store.init();
		try {
			BackupResult full = fullBackup(store, backups);
			TripleStore triples = store.getBackingStore().getTripleStore();
			byte[] before = namespaceDatabaseDescriptor(triples);
			var namespaces = triples.readNamespaceSnapshot();
			add(store, "ordinary-statement");
			BackupResult incremental = incrementalBackup(store, backups, full.getEndTransactionId());
			assertEquals(full.getEndTransactionId() + 1, incremental.getEndTransactionId());
			assertEquals(namespaces, triples.readNamespaceSnapshot(), "This commit must not change RDF namespaces");
			assertArrayEquals(before, namespaceDatabaseDescriptor(triples),
					"An ordinary backup-stage commit must not rewrite the namespace database root or metadata");
		} finally {
			store.shutDown();
		}
	}

	@Test
	void journaledCommitDoesNotForceBackupSyncOnWriter(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = journaledConfig();
		assertFalse(config.getForceSync());
		LmdbStore store = new LmdbStore(directory.resolve("live").toFile(), config);
		store.init();
		try {
			Path backups = directory.resolve("backups");
			BackupResult full = fullBackup(store, backups);
			int tripleFlags = store.getBackingStore()
					.getTripleStore()
					.getTxnManager()
					.doWithFreshPriority((stack, txn) -> {
						var flags = stack.mallocInt(1);
						E(mdb_env_get_flags(mdb_txn_env(txn), flags));
						return flags.get(0);
					});
			ValueStore dictionary = store.getBackingStore().valueStore();
			int valueFlags;
			dictionary.startTransaction(false);
			try {
				valueFlags = dictionary.withWriterCaptureContext((stack, txn) -> {
					var flags = stack.mallocInt(1);
					E(mdb_env_get_flags(mdb_txn_env(txn), flags));
					return flags.get(0);
				});
			} finally {
				dictionary.rollback();
			}
			assertEquals(0, tripleFlags & (MDB_NOSYNC | MDB_NOMETASYNC),
					"A journaled commit must make triples durable before returning to its caller");
			assertEquals(0, valueFlags & (MDB_NOSYNC | MDB_NOMETASYNC),
					"The dictionary must share the enabled journal's durable commit policy");
			Thread writer = Thread.currentThread();
			var syncThreads = new CopyOnWriteArrayList<Thread>();
			store.getBackingStore().valueStore().setBeforeBackupSync(() -> {
				syncThreads.add(Thread.currentThread());
			});
			store.getBackingStore().getTripleStore().setBeforeBackupSync(() -> {
				syncThreads.add(Thread.currentThread());
			});
			add(store, "writer-durability");
			incrementalBackup(store, backups, full.getEndTransactionId());
			assertFalse(syncThreads.contains(writer), "Backup must not force native sync on the committing thread");
		} finally {
			store.shutDown();
		}
	}

	private static byte[] namespaceDatabaseDescriptor(TripleStore triples) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			var database = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, (ByteBuffer) null, 0, database));
			MDBVal key = MDBVal.malloc(stack)
					.mv_data(stack.bytes(TripleStore.NAMESPACE_DATABASE_NAME.getBytes(StandardCharsets.US_ASCII)));
			MDBVal value = MDBVal.malloc(stack);
			E(mdb_get(transaction, database.get(0), key, value));
			// Compare the opaque catalog value, including its root. Counts alone miss same-size rewrites.
			ByteBuffer bytes = Objects.requireNonNull(value.mv_data()).duplicate();
			byte[] descriptor = new byte[bytes.remaining()];
			bytes.get(descriptor);
			return descriptor;
		});
	}

	private static LmdbStoreConfig journaledConfig() {
		return new LmdbStoreConfig("spoc,posc").setBackupJournalEnabled(true);
	}

	private static BackupResult fullBackup(LmdbStore store, Path backups) {
		return store.getBackupService().createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
	}

	private static BackupResult incrementalBackup(LmdbStore store, Path backups, long since) {
		return store.getBackupService()
				.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
						.sinceTransactionId(since)
						.build());
	}

	private static void add(LmdbStore store, String name) {
		var vf = SimpleValueFactory.getInstance();
		try (SailConnection connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(vf.createIRI("urn:backup-performance:" + name), vf.createIRI("urn:predicate"),
					vf.createLiteral(name));
			connection.commit();
		}
	}
}
